<script lang="ts">
 import {invalidateAll} from '$app/navigation';let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();let name=$state(''),lot=$state(''),parameter=$state('temperature'),unit=$state('°C'),method=$state(''),busy=$state(false),message=$state(''),token=$state(''),endpoint=$state('');
 async function create(){busy=true;try{const res=await fetch('/api/sensors',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,lot_id:lot,parameter,unit,method})});const result=await res.json();if(res.ok){token=result.token;endpoint=result.endpoint;await invalidateAll();}else message=t(result.message);}finally{busy=false;}}
</script>
<section class="card"><h2>{t('sensors')}</h2><p class="muted">{t('sensorHint')}</p><form onsubmit={(e)=>{e.preventDefault();create();}}><div class="grid"><label>{t('name')}<input bind:value={name} required /></label><label>{t('lot_id')}<select bind:value={lot} required><option value="">—</option>{#each model.lots as l}<option value={l.id}>{l.code}</option>{/each}</select></label><label>{t('parameter')}<select bind:value={parameter}>{#each ['temperature','sugar','alcohol','acidity','ph','free_so2'] as p}<option value={p}>{p==='ph'?'pH':t(p)}</option>{/each}</select></label><label>{t('unit')}<input bind:value={unit} required /></label><label>{t('method')}<input bind:value={method} required /></label></div><button disabled={busy}>{t('createSensor')}</button></form>{#if token}<p>{t('tokenOnce')}</p><pre>{endpoint}
Authorization: Bearer {token}
{JSON.stringify({message_id:'unique-message-0001',records:[{measured_at:new Date().toISOString(),value:'18.5'}]},null,2)}</pre><button onclick={()=>token=''}>{t('hideToken')}</button>{/if}<p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f1;padding:15px;font-size:11px}</style>
